CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE TABLE experts (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(160) NOT NULL,
        "Capacity" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        "LastAssignedAt" timestamp with time zone,
        CONSTRAINT "PK_experts" PRIMARY KEY ("Id"),
        CONSTRAINT ck_experts_capacity_positive CHECK ("Capacity" > 0)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE TABLE specialties (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        CONSTRAINT "PK_specialties" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE TABLE expert_specialties (
        "ExpertId" integer NOT NULL,
        "SpecialtyId" integer NOT NULL,
        CONSTRAINT "PK_expert_specialties" PRIMARY KEY ("ExpertId", "SpecialtyId"),
        CONSTRAINT "FK_expert_specialties_experts_ExpertId" FOREIGN KEY ("ExpertId") REFERENCES experts ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_expert_specialties_specialties_SpecialtyId" FOREIGN KEY ("SpecialtyId") REFERENCES specialties ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE TABLE requests (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "RequestKey" character varying(200) NOT NULL,
        "SpecialtyId" integer NOT NULL,
        "Priority" integer NOT NULL,
        "Status" integer NOT NULL,
        "AssignedExpertId" integer,
        "CreatedAt" timestamp with time zone NOT NULL,
        "AssignedAt" timestamp with time zone,
        "ClosedAt" timestamp with time zone,
        CONSTRAINT "PK_requests" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_requests_experts_AssignedExpertId" FOREIGN KEY ("AssignedExpertId") REFERENCES experts ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_requests_specialties_SpecialtyId" FOREIGN KEY ("SpecialtyId") REFERENCES specialties ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE TABLE assignment_history (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "RequestId" bigint NOT NULL,
        "ExpertId" integer NOT NULL,
        "AssignedAt" timestamp with time zone NOT NULL,
        "UnassignedAt" timestamp with time zone,
        CONSTRAINT "PK_assignment_history" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_assignment_history_experts_ExpertId" FOREIGN KEY ("ExpertId") REFERENCES experts ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_assignment_history_requests_RequestId" FOREIGN KEY ("RequestId") REFERENCES requests ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE INDEX "IX_assignment_history_ExpertId" ON assignment_history ("ExpertId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE INDEX "IX_assignment_history_RequestId" ON assignment_history ("RequestId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE INDEX "IX_expert_specialties_SpecialtyId" ON expert_specialties ("SpecialtyId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE INDEX "IX_experts_IsActive" ON experts ("IsActive");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE INDEX "IX_requests_AssignedExpertId_Status" ON requests ("AssignedExpertId", "Status");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_requests_RequestKey" ON requests ("RequestKey");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE INDEX "IX_requests_SpecialtyId" ON requests ("SpecialtyId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE INDEX "IX_requests_Status_Priority_CreatedAt" ON requests ("Status", "Priority", "CreatedAt");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_specialties_Name" ON specialties ("Name");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261110102657_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261110102657_InitialCreate', '10.0.0');
    END IF;
END $EF$;
COMMIT;

